def migrar_planes_servicios_a_detalle(apps, schema_editor):
    table_names = set(schema_editor.connection.introspection.table_names())
    tabla_origen = "contratos_planservicio_servicios"
    if tabla_origen not in table_names:
        return

    PlanServicioDetalle = apps.get_model("contratos", "PlanServicioDetalle")
    with schema_editor.connection.cursor() as cursor:
        cursor.execute(
            f"""
            SELECT planservicio_id, servicio_id
            FROM {tabla_origen}
            ORDER BY planservicio_id, id
            """
        )
        rows = cursor.fetchall()

    ahora = timezone.now()
    orden_por_plan = {}
    crear = []
    for plan_id, servicio_id in rows:
        orden = orden_por_plan.get(plan_id, 0)
        orden_por_plan[plan_id] = orden + 1
        crear.append(
            PlanServicioDetalle(
                plan_id=plan_id,
                servicio_version_id=servicio_id,
                orden=orden,
                obligatorio=True,
                cantidad_default=1,
                veces_por_mes_default=1,
                fecha_creacion=ahora,
                fecha_modificacion=ahora,
            )
        )

    if crear:
        PlanServicioDetalle.objects.bulk_create(crear, ignore_conflicts=True)


